from cache import TTLCache

class Clock:
    def __init__(self, t=0.0):
        self.t = t
    def __call__(self):
        return self.t

rng = random.Random(1234)
for trial in range(8):
    capacity = rng.choice([0, 1, 2, 3, 5])
    ttl = rng.choice([0, 1, 2, 5, 10])
    clk = Clock(rng.uniform(0, 5))
    c = TTLCache(capacity, ttl, clk)
    oracle = {}
    seq = 0
    log = []
    for step in range(300):
        clk.t += rng.choice([0.0, 0.25, 0.5, 1.0, 2.0, 10.0])
        op = rng.random()
        key = rng.choice('abcdef')
        if op < 0.5:
            value = rng.randint(0, 1000)
            c.put(key, value)
            for k in [k for k, e in oracle.items() if clk.t - e[1] >= ttl]:
                del oracle[k]
            if capacity > 0:
                oracle.pop(key, None)
                while len(oracle) >= capacity:
                    lru = min(oracle, key=lambda k: oracle[k][2])
                    del oracle[lru]
                seq += 1
                oracle[key] = [value, clk.t, seq]
            log.append(f'step{step} t={clk.t!r} PUT {key!r}={value}')
        else:
            seq += 1
            got = c.get(key)
            for k in [k for k, e in oracle.items() if clk.t - e[1] >= ttl]:
                del oracle[k]
            expected = None
            if key in oracle:
                oracle[key][2] = seq
                expected = oracle[key][0]
            log.append(f'step{step} t={clk.t!r} GET {key!r} got={got!r} exp={expected!r}')
            if got != expected:
                print('DIVERGENCE', trial, capacity, ttl, clk.t, key, got, expected)
                print('\n'.join(log[-25:]))
                print('cache data:', {k: (v[0], v[1]) for k, v in c.data.items()})
                print('oracle:', {k: tuple(v) for k, v in oracle.items()})
                raise SystemExit(1)
    if trial == 7:
        live = {k: e[0] for k, e in oracle.items() if clk.t - e[1] < ttl and capacity > 0}
        print('trial7 end: capacity', capacity, 'ttl', ttl, 't', clk.t)
        print('cache:', {k: (v[0], v[1]) for k, v in c.data.items()})
        print('oracle live:', live)
        for k, v in live.items():
            print('  get', k, '->', c.get(k), 'expected', v)
print('no divergence')
